head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > P > closable]<br/>컴포넌트의 Tab 버튼 영역에서 '닫기' 버튼을 활성화 시킬지 설정합니다.",
    "validation" : [
        "Tabs 의 closable 속성을 설정하지 않으면 TabControl 컴포넌트의 closable 속성이 적용됩니다.",
        "미설정 또는 false 설정 시 Tab 버튼 영역에 마우스를 오버해도 '닫기' 버튼을 표시하지 않습니다.",        
        "true 설정 시 Tab 버튼 영역에 마우스 오버 시 '닫기' 버튼이 표시됩니다.",
        "'닫기' 버튼 클릭 시 해당 Tab 페이지가 TabControl 컴포넌트에서 제거됩니다.",        
        "Tab 페이지가 제거되면 나머지 Tab 페이지의 인덱스가 재설정됩니다.",
        "선택 상태인 Tab 페이지가 제거되면 다음 Tab 페이지가 선택됩니다.",
        "제거된 Tab 페이지가 마지막 Tab 페이지인 경우 이전 Tab 페이지가 선택됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        closable: con_closable.getText(),
    };

    let cList = $c.gcm.createCList(properties);      
    let eList = $c.gcm.createEList(["onchange", "ontabclose"]);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs3" label="Tabs3"></w2:tabs>';
    strTarget += '<w2:content style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; height:23px; " id="" label="tabs1"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content2">';
    strTarget += '<xf:input id="" style="width:144px; height:21px; " initValue="tabs2"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content3">';    
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );
}



scwin.target1_ontabclose = function (tabId, index, userTabId) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_ontabclose=====");
}



scwin.target1_onchange = function (tabId, index, userTabId) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");
    wf_body_bottom.getObj("scwin").setReturnValue("tabId : " + tabId);
    wf_body_bottom.getObj("scwin").setReturnValue("index : " + index);
}
